fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let len_a = a.len();
    let len_b = b.len();
    let max_len = len_a.max(len_b);

    let mut output_a = Vec::with_capacity(max_len);
    let mut output_b = Vec::with_capacity(max_len);

    if len_a == 1 {
        // Repeat the single value in `a` to fill `output_a`
        let value_a = a[0];
        output_a.extend(std::iter::repeat(value_a).take(max_len));
    } else {
        // Copy `a` directly into `output_a`
        output_a.extend(&a);
    }

    if len_b == 1 {
        // Repeat the single value in `b` to fill `output_b`
        let value_b = b[0];
        output_b.extend(std::iter::repeat(value_b).take(max_len));
    } else {
        // Copy `b` directly into `output_b`
        output_b.extend(&b);
    }

    // If one of the arrays is shorter, we need to fill the rest with the longer array
    if len_a < max_len {
        output_a.extend(std::iter::repeat(a[len_a - 1]).take(max_len - len_a));
    }
    if len_b < max_len {
        output_b.extend(std::iter::repeat(b[len_b - 1]).take(max_len - len_b));
    }

    (output_a, output_b)
}